import { renderResults, loadResults } from '../shared/page.js';

export function updateProductResults(state) {
  return renderResults(state);
}

export function mountProductPage(state) {
  return updateProductResults(state);
}

export async function fetchProductResults(state) {
  return await loadResults(state);
}

export async function openProductRoute(state) {
  return await fetchProductResults(state);
}

export function initializePage(state) {
  return state.remote ? openProductRoute(state) : mountProductPage(state);
}
// Executed fixture contract: the response contains an explicit null displayName.
export function mapTransactionDetail(response) {
  return { merchant: response.merchant.displayName.trim() };
}
export function renderTransactionDetail(response) {
  return mapTransactionDetail(response);
}
export function buildTransferView(state) {
  if (!state.recipient) throw new Error('Transfer view requires a selected recipient');
  return { recipientLabel: state.recipient.label };
}
export function readPrice(record) {
  return record.price.amount;
}

export function formatPrice(record) {
  return record.formatPrice(record.price);
}

export function buildPriceRows(records, formatter) {
  return records.map(formatter);
}

export function saveRecentlyViewed(value) {
  localStorage.setItem('vantra:recently-viewed', value);
}

export function hydrateResults(serverText, clientText) {
  if (serverText !== clientText) {
    throw new Error('Hydration failed: the server-rendered results do not match the client state.');
  }
  return clientText;
}
export function decodeResponse(body) {
  return JSON.parse(body);
}

export async function requestCollection(url) {
  const response = await fetch(url);
  const body = await response.text();
  return decodeResponse(body);
}

export async function cancelRequest(url) {
  const controller = new AbortController();
  controller.abort();
  return await fetch(url, { signal: controller.signal });
}
export async function importRoute(url) {
  return await import(url);
}

export function loadRouteChunk(url, chunkId) {
  return new Promise(function resolveChunk(resolve, reject) {
    const script = document.createElement('script');
    script.src = url;
    script.onload = resolve;
    script.onerror = function handleChunkError() {
      const error = new Error('Loading chunk ' + chunkId + ' failed.\n(error: ' + url + ')');
      error.name = 'ChunkLoadError';
      reject(error);
    };
    document.head.appendChild(script);
  });
}
import { renderTransactionDetail, buildTransferView } from './transaction.js';
import { readPrice, formatPrice, buildPriceRows, saveRecentlyViewed, hydrateResults } from './catalog.js';
import { requestCollection, cancelRequest } from './client.js';
import { importRoute, loadRouteChunk } from './router.js';

export function renderResults(state) {
  switch (state.operation) {
    case 'contract_null': return renderTransactionDetail({ merchant: { displayName: null } });
    case 'view_state': return buildTransferView({ recipient: null });
    case 'property_undefined': return buildPriceRows(state.records, readPrice);
    case 'not_a_function': return buildPriceRows(state.records, formatPrice);
    case 'quota_exceeded': return saveRecentlyViewed(state.recent);
    case 'hydration': return hydrateResults(state.serverText, state.clientText);
    default: return state.records;
  }
}

export async function loadResults(state) {
  switch (state.operation) {
    case 'abort': return await cancelRequest(state.endpoint);
    case 'chunk_load': return await importRoute(state.chunk);
    case 'webpack_chunk_load': return await loadRouteChunk(state.chunk, state.chunkId);
    default: return await requestCollection(state.endpoint);
  }
}

